  function tok(n) { return getComputedStyle(document.documentElement).getPropertyValue(n).trim(); }
  function rgb(h) { h = h.replace('#', ''); var n = parseInt(h, 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }
  function alpha(h, a) { var c = rgb(h); return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
  function mix(h1, h2, t) { var a = rgb(h1), b = rgb(h2); return 'rgb(' + [0, 1, 2].map(function (i) { return Math.round(a[i] + (b[i] - a[i]) * t); }).join(',') + ')'; }
  function setText(id, v) { var el = document.getElementById(id); if (el) el.textContent = v; }
  function sg(v, d) { return (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(d === undefined ? 2 : d); }
  var K = {}; ['co2', 'ch4', 'o3', 'aer', 'other', 'heat', 'fire', 'health', 'eco', 'tox', 'good', 'bad', 'muted'].forEach(function (k) { K[k] = tok('--k-' + k); });
  var INK = tok('--text'), MUTED = tok('--text-muted'), PAPER = tok('--bg-card');

  /* whisker plugin: draws lo–hi ranges on a bar dataset */
  function whiskers(lo, hi, horizontal) {
    return { id: 'wh' + Math.random().toString(36).slice(2, 7), afterDatasetsDraw: function (ch) {
      var m = ch.getDatasetMeta(0), sc = horizontal ? ch.scales.x : ch.scales.y, ctx = ch.ctx;
      ctx.save(); ctx.strokeStyle = alpha(INK, 0.75); ctx.lineWidth = 1.3;
      m.data.forEach(function (b, i) {
        if (lo[i] === null || lo[i] === undefined) return;
        var a = sc.getPixelForValue(lo[i]), z = sc.getPixelForValue(hi[i]);
        ctx.beginPath();
        if (horizontal) { ctx.moveTo(a, b.y); ctx.lineTo(z, b.y); ctx.moveTo(a, b.y - 5); ctx.lineTo(a, b.y + 5); ctx.moveTo(z, b.y - 5); ctx.lineTo(z, b.y + 5); }
        else { ctx.moveTo(b.x, a); ctx.lineTo(b.x, z); ctx.moveTo(b.x - 6, a); ctx.lineTo(b.x + 6, a); ctx.moveTo(b.x - 6, z); ctx.lineTo(b.x + 6, z); }
        ctx.stroke();
      });
      ctx.restore(); } };
  }

